WITH DailySummaries AS ( SELECT DATE(order_date) AS sale_date, SUM(total_amount) AS daily_total_sales, COUNT(*) AS daily_total_orders FROM orders WHERE status = 'PAID' AND DATE(order_date) BETWEEN #{startDate} AND #{endDate}
AND branch_code = #{branchCode}
GROUP BY sale_date ) SELECT ds.sale_date AS sale_date, ds.daily_total_sales AS total_sales, ds.daily_total_orders AS total_orders, SUM(ds.daily_total_sales) OVER (ORDER BY ds.sale_date) AS cumulative_sales FROM DailySummaries ds ORDER BY ds.sale_date ASC;

SELECT HOUR(created_at) AS hour, SUM(total_amount) AS total_sales, COUNT(*) AS total_orders FROM orders WHERE status = 'PAID' AND DATE(order_date) = #{targetDate}
AND branch_code = #{branchCode}
GROUP BY HOUR(created_at) ORDER BY hour ASC;

SELECT r.name AS menu_name, SUM(om.qty) AS quantity, SUM(om.line_total_amount) AS total_sales FROM orders o JOIN order_menu om ON o.order_id = om.order_id JOIN recipe r ON om.recipe_code = r.recipe_code WHERE o.status = 'PAID' AND DATE(o.order_date) = #{targetDate}
AND o.branch_code = #{branchCode}
AND r.category_id = #{categoryId}
AND r.sub_category_code = #{subCategoryCode}
GROUP BY r.name ORDER BY total_sales DESC;

SELECT
    recipe_code as recipe_code,
    name as menu_name
FROM recipe
WHERE category_id = #{categoryId}
ORDER BY name;
